# Alert: Detects deployments with CPU usage between 40% and 75%
# Purpose: Identify workloads in moderate CPU range - may need monitoring or minor optimization

(
  avg by (replicaset, deployment) (
    (
      # Calculate average CPU usage per container
      label_replace(
        rate(container_cpu_usage_seconds_total{
          metrics_path="/metrics/cadvisor",
          container!="",  # Filter out empty container names (system containers)
          cluster="$cluster",  # Dynamic cluster selector from Grafana variable
          image!="",  # Filter out init containers and pods without images
        }[1m]),  # 1-minute average rate for smoothing
        # Extract replicaset name from pod naming pattern
        # Example: "frontend-7cbb49cd8" → replicaset="frontend"
        "replicaset", "$1", "pod", "(.+)-[a-z0-9]+$"
      )
    )
    *
    # Enrich metrics with application group label from pod metadata
    on(pod) group_left(rems_application_group)
    kube_pod_labels{
      rems_application_group="$ApplicationGroup",  # Filter by selected application group
    }
  ) > 0.4  # Lower threshold: CPU usage greater than 40%
)
and
(
  # Same calculation as above but with different threshold
  avg by (replicaset, deployment) (
    (
      label_replace(
        rate(container_cpu_usage_seconds_total{
          metrics_path="/metrics/cadvisor",
          container!="",
          cluster="$cluster",
          image!="",
        }[1m]),
        "replicaset", "$1", "pod", "(.+)-[a-z0-9]+$"
      )
    )
    *
    on(pod) group_left(rems_application_group)
    kube_pod_labels{
      rems_application_group="$ApplicationGroup",
    }
  ) < 0.75  # Upper threshold: CPU usage less than 75%
)

# Result: Shows deployments where:
# - CPU usage is > 40% (moderate utilization)
# - CPU usage is < 75% (not critical yet)
# Useful for: Proactive monitoring, capacity planning, identifying growing workloads

# Alert: Containers exceeding 75% CPU usage

avg by (replicaset, deployment) (
  (
    # Calculate CPU utilization rate for each container
    label_replace(
      rate(container_cpu_usage_seconds_total{
        metrics_path="/metrics/cadvisor",  # Source metric from cAdvisor
        container!="",                     # Filter out system/empty containers
        image!=""                          # Filter out init containers
      }[1m]),                              # 1-minute average rate

      # Extract replicaset name from pod naming convention
      # Example: "api-deployment-abc123" → "api-deployment"
      "replicaset", "$1", "pod", "(.+)-[a-z0-9]+$"
    )
  )
  * 
  # Enrich with application group label from pod metadata
  on(pod) group_left(rems_application_group)
  kube_pod_labels{
    rems_application_group="$ApplicationGroup",  # Dynamic app group filter
  }
) > 0.75  # Threshold: 75% CPU utilization

# Shows replicasets/deployments where average container CPU > 75%

# Alert: Detects deployments with memory usage between 40% and 75% of limit
# Purpose: Identify workloads in optimal memory range - healthy utilization without risk

(
  # Check for memory usage GREATER than 40% of limit
  (
    avg by (replicaset, deployment) (
      (
        # Calculate memory utilization percentage: (usage / limit) * 100
        label_replace(
          container_memory_usage_bytes{
            metrics_path="/metrics/cadvisor",  # Source: container metrics
            container!="",  # Exclude system containers (empty names)
            image!="",  # Exclude init containers and sidecars
          },
          # Extract replicaset name from pod naming convention
          # Pattern: <deployment-name>-<random-hash> → <deployment-name>
          "replicaset", "$1", "pod", "(.+)-[a-z0-9]+$"
        )
        /
        label_replace(
          container_spec_memory_limit_bytes{
            metrics_path="/metrics/cadvisor",
            container!="",
            image!="",
            # Note: Only includes containers with memory limits set
          },
          "replicaset", "$1", "pod", "(.+)-[a-z0-9]+$"
        )
      ) * 100  # Convert to percentage
    )
    *
    # Add application group label for filtering
    on(pod) group_left(rems_application_group)
    kube_pod_labels{
      rems_application_group="$ApplicationGroup",  # Dynamic app group filter
    }
  ) > 40  # Lower bound: Above 40% utilization
)
and
(
  # Check for memory usage LESS than 75% of limit
  (
    avg by (replicaset, deployment) (
      (
        # Same calculation repeated (Prometheus requires separate evaluation)
        label_replace(
          container_memory_usage_bytes{
            metrics_path="/metrics/cadvisor",
            container!="",
            image!="",
          },
          "replicaset", "$1", "pod", "(.+)-[a-z0-9]+$"
        )
        /
        label_replace(
          container_spec_memory_limit_bytes{
            metrics_path="/metrics/cadvisor",
            container!="",
            image!="",
          },
          "replicaset", "$1", "pod", "(.+)-[a-z0-9]+$"
        )
      ) * 100
    )
    *
    on(pod) group_left(rems_application_group)
    kube_pod_labels{
      rems_application_group="$ApplicationGroup",
    }
  ) < 75  # Upper bound: Below 75% utilization
)

# Result: Shows deployments where:
# - Memory usage > 40% of limit (good utilization, not wasted)
# - Memory usage < 75% of limit (safe buffer before OOM risk)
# Ideal range for: Performance tuning, capacity planning, avoiding OOM kills

# Alert: Detects services with low successful request rate (<90%)
# Purpose: Identify services with high error rates or availability issues

(
  # Calculate success rate percentage for each service
  sum by (rems_service) (
    # Count of successful HTTP requests (2xx and 3xx status codes)
    traces_span_metrics_duration_milliseconds_count{
      span_kind="SPAN_KIND_SERVER",  # Filter: Server-side spans only
      http_status_code=~"^2.*|^3.*"  # Regex: Status codes starting with 2 or 3
    }
  )
  /
  # Total count of all HTTP requests (successful + failed)
  sum by (rems_service) (
    traces_span_metrics_duration_milliseconds_count{
      span_kind="SPAN_KIND_SERVER"  # Same filter for total count
    }
  )
) * 100 < 90  # Threshold: Less than 90% success rate

# Formula: (Successful requests ÷ Total requests) × 100 < 90%
# Interpretation: Service is failing more than 10% of requests

# Alert: Detects services with success rate between 90% and 99.99%
# Purpose: Identify services with moderate error rates needing attention

(
  # Check for success rate GREATER than 90%
  sum by (rems_service) (
    # Count of successful requests (HTTP 2xx and 3xx responses)
    traces_span_metrics_duration_milliseconds_count{
      span_kind="SPAN_KIND_SERVER",  # Server-side spans only
      http_status_code=~"^2.*|^3.*"  # Regex: Status codes 200-299, 300-399
    }
  )
  /
  # Total request count for denominator
  sum by (rems_service) (
    traces_span_metrics_duration_milliseconds_count{
      span_kind="SPAN_KIND_SERVER"  # All server requests
    }
  )
) * 100 > 90  # Lower bound: Above 90% success rate
and
(
  # Check for success rate LESS than or equal to 99.99%
  sum by (rems_service) (
    # Same successful request count
    traces_span_metrics_duration_milliseconds_count{
      span_kind="SPAN_KIND_SERVER",
      http_status_code=~"^2.*|^3.*"
    }
  )
  /
  # Same total request count
  sum by (rems_service) (
    traces_span_metrics_duration_milliseconds_count{
      span_kind="SPAN_KIND_SERVER"
    }
  )
) * 100 <= 99.99  # Upper bound: Up to 99.99% success rate

# Success Rate Calculation:
# (2xx + 3xx responses) ÷ (All responses) × 100
#
# Threshold Interpretation:
# - > 90%: Not critically failing (above alerting threshold)
# - <= 99.99%: Not perfect (allows up to 0.01% error rate)

# Alert: Detects services with low but non-zero request rates (1-10 requests/sec)
# Purpose: Identify lightly loaded or idle services

sum by(service_name) (
  # Calculate requests per second for each service
  rate(
    traces_span_metrics_duration_milliseconds_count{
      service_name=~".*",  # Match all service names (wildcard)
      span_kind="SPAN_KIND_SERVER"  # Only server-side spans
    }[1m]  # 1-minute moving average rate calculation
  )
) > 0  # Condition 1: Request rate is greater than 0 RPS (active)
and
sum by(service_name) (
  # Same rate calculation for the second condition
  rate(
    traces_span_metrics_duration_milliseconds_count{
      service_name=~".*",
      span_kind="SPAN_KIND_SERVER"
    }[1m]
  )
) <= 10  # Condition 2: Request rate is 10 RPS or less (low traffic)

# HOW RATE() WORKS:
# rate(metric[1m]) = (current_value - value_1_minute_ago) ÷ 60 seconds
# Returns: Average requests per second over the last minute

# Alert: Detects services with moderate to high request rates (11-6000 requests/sec)
# Purpose: Identify actively used services with substantial traffic

sum by(service_name) (
  # Calculate requests per second (RPS) for each service
  rate(
    traces_span_metrics_duration_milliseconds_count{
      service_name=~".*",  # Include all services
      span_kind="SPAN_KIND_SERVER"  # Server-side spans only
    }[1m]  # 1-minute average rate
  )
) > 10  # Lower threshold: More than 10 requests per second
and
sum by(service_name) (
  # Same RPS calculation for upper bound check
  rate(
    traces_span_metrics_duration_milliseconds_count{
      service_name=~".*",
      span_kind="SPAN_KIND_SERVER"
    }[1m]
  )
) <= 6000  # Upper threshold: 6000 RPS or less

# THRESHOLD BREAKDOWN:
# - > 10 RPS: Beyond low-traffic range (not idle/background)
# - <= 6000 RPS: Below extreme high-load threshold (6000 = 6k RPS)
